const usd = { minor: 1999n, currency: 'USD', scale: 2 };
const add = (a, b) => {
  if (a.currency !== b.currency) throw new TypeError('currency mismatch');
  return { ...a, minor: a.minor + b.minor };
};
new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD' })
  .format(toDecimalString(usd));          // "$19.99", formatted only at the edge

