import { dinero, add, allocate, toDecimal } from 'dinero.js';
import { USD } from 'dinero.js/currencies';

const d1 = dinero({ amount: 500, currency: USD });
const [a, b] = allocate(add(d1, d1), [1, 1]);   // no minor unit is lost
toDecimal(a);                                   // "5.00"
